    project: p.project, version: p.version, publishedAt: p.published_at,
    manifestUrl, releaseUrl, publisher: repo.split('/')[0], capabilities,
    platforms: unique(p.artifacts.filter((a: any) => a.os && a.arch).map((a: any) =>
      [a.os === 'darwin' ? 'macOS' : a.os === 'linux' ? 'Linux' : a.os === 'windows' ? 'Windows' : a.os,
