  { label: 'Homebrew installs', value: latest.brewInstalls?.toLocaleString() ?? '—', note: 'Rolling 30 days · install-on-request' },
  { label: 'Homebrew rank', value: latest.brewRank === null ? '—' : `#${latest.brewRank}`, note: 'Among install-on-request formulae' },
  { label: 'Homebrew share', value: latest.brewPercent === null ? '—' : `${latest.brewPercent}%`, note: 'Share of install-on-request installs' },
];
const charts = [
  { title: 'GitHub stars', key: 'stars' as const, color: 'var(--accent)' },
  { title: 'Homebrew installs · rolling 30 days', key: 'brewInstalls' as const, color: 'var(--data)' },
];
---
