  <div class="adoption-charts">{charts.map(chart => {
    const valid = points.filter(p => p[chart.key] !== null);
    if (!valid.length) return null;
    const max = Math.max(...valid.map(p => p[chart.key]!), 1);
    const firstTime = Date.parse(points[0].date);
    const range = Math.max(Date.parse(latest.date) - firstTime, 1);
    const x = (date: string) => 48 + (Date.parse(date) - firstTime) / range * 464;
    const y = (value: number) => 172 - value / max * 140;
    // Break the line at missing observations instead of interpolating across them.
