      <svg viewBox="0 0 540 205" role="img" aria-label={`${chart.title} from ${points[0].date} to ${latest.date}. Latest value ${latest[chart.key]?.toLocaleString() ?? 'unavailable'}. Full daily values are in the source data.`}>
