        <path d={path} fill="none" stroke={chart.color} stroke-width="2.5" stroke-linejoin="round" />
        <text x="48" y="197">{points[0].date}</text><text x="512" y="197" text-anchor="end">{latest.date}</text>
      </svg>
    </div>;
  })}</div>
